    expect(avails[0]!.externalBreakId).toBe("BRK-first");
    expect(avails[1]!.externalBreakId).toBeUndefined();
  });

  it("detects multiple avails in one window", () => {
    const m = manifest([
      "#EXT-X-MEDIA-SEQUENCE:0",
      "#EXT-X-CUE-OUT:30",
      "#EXTINF:6.000,",
